    Assert.assertEquals(stats.queueSize(), 2);
    Assert.assertEquals(stats.fillRatio(), 1d);
    Assert.assertEquals(stats.getAttemptCount(), 7);
    Assert.assertEquals(stats.putAttemptCount(), 8);
}

